"""Serialize manually read and adjudicated claims. No keyword-generated verdicts.
Only source line ranges and short, explicitly anchored quotations are mechanically located.
"""
import json,pathlib,csv
BASE=pathlib.Path(__file__).resolve().parents[2]
ROOT=BASE.parent
OUT=pathlib.Path(__file__).parent
pages=json.loads((BASE/'source_audit/page_index.json').read_text())
claims=[]

def add(n,scans,topic,his,statement,status,klass,fate,refs,comp='No numerical computation; logical or categorical statement.',confidence='high',date=None):
    selected=[p for p in pages if p['cote']=='43' and '/codex/' in p['file'] and int(p['scan']) in scans]
    loc=[f"{p['file']}:{p['line_start']}-{p['line_end']} (scan {p['scan']}; {topic})" for p in selected]
    claims.append(dict(id=f'CL-SA19-{n:03d}',items=[],cote='43',scans=scans,lines=loc,his_statement=his,
        statement=statement,status_on_pages=status,computation=comp,**{'class':klass},fate=fate,
        fate_date=date or 'Dates distinguished in the cited reference records; manuscript sheets generally undated.',
        present_status='As of 19 November 2026: '+fate,refs=refs,confidence=confidence))

add(601,[4,8],'ray class and idèle quotients',r'The ray-class sequences and $C_{\mathfrak m}=C/C^0_{\mathfrak m}$, with the displayed local factors.',
    'For a number field and a modulus, the ray class group is the idèle class group modulo local principal units at the modulus, local units away from it, and the prescribed positive components at real places. The unit/residue/ideal-class sequence is exact.',
    'proof sketched','E','Classical ray class and idèle formulations: Milne CFT V §§1,4. The printed all-K_v^* factors outside S require the correction in C1; the corrected theorem is established.', ['MilneCFT2020'],'proofs.md C1; exact_checks.py ray_sign_mod_*')
add(602,[4],'unit congruence cofinality',r'Every subgroup of finite index in the unit group contains a congruence subgroup.',
    'For a number field K and finitely generated E⊂K*, every finite-index subgroup H⊂E contains {u∈E:u≡1 mod a} for some nonzero ideal a (with denominators excluded).',
    'stated without proof','E','Chevalley (1951), Theorem I, proves the needed power-congruence statement; choosing an exponent for E/H gives precisely this consequence.', ['Chevalley1951'],'proofs.md C1; implication checked from Theorem I',date='Published May 1951; first circulation not established.')
add(603,[5,10],'nonabelian Artin target',r'$\psi:I_{\mathfrak m}\to G$; later $G/G\prime$.',
    'The Artin map for a finite Galois extension takes ideal classes to the abelianization of its Galois group; an unrestricted homomorphism with all Frobenius values in nonabelian G is not defined.',
    'corrected by himself later','E','Scan10 replaces the unrestricted target on5 by G/G′. Modern reciprocity has an abelian target; this is a correction within the dossier, not a new conjecture.', ['MilneCFT2020'])
add(604,[6,7],'norm-one compactness, units and class number',r'$C^0$ compact; Dirichlet, Minkowski; finite $h$ and the real torus description.',
    'For a number field, the norm-one idèle class group is compact; the ideal class group is finite, and the units form roots of unity times Z^(r1+r2−1). The archimedean quotient has the indicated torus factor.',
    'proof sketched','E','Classical Dirichlet–Minkowski structure; Milne CFT V §4. The E0 intermediate quotient is not a correct application of the second isomorphism theorem.', ['MilneCFT2020'],'proofs.md C1 checks the quotient; no computational proof of Minkowski claimed.')
add(605,[7],'E0 intermediate quotient',r'$E_0=P\cap D_\infty\simeq(P+D_\infty)/P$.',
    'The correct group identity is (P+D∞)/P≅D∞/(P∩D∞); the intersection itself is not the quotient. This corrects only the intermediate identification, not the unit-rank theorem.',
    'false as stated','E','Elementary second isomorphism theorem. Mathematical defect established; its origin in ink or transcription is undecided.', ['MilneCFT2020'],'proofs.md C1')
add(606,[8,9,10],'weak approximation and local Artin representative',r'Choose $a\equiv x$ at the specified places and associate the divisor of $a$.',
    'Weak approximation constructs the representative. For the usual valuation divisor map, removing the principal idele a gives −div(a) outside the modulus. An inverse convention can reverse both signs consistently.',
    'proof sketched','E','Weak approximation and idelic reciprocity are established; the printed representative sign is convention-sensitive and flagged rather than silently altered.', ['MilneCFT2020'],'proofs.md C1; exact mod5 sign certificate')
add(607,[10,11,12,13],'reciprocity existence norm limitation',r'Artin–Takagi reciprocity, existence, and local/global norm compatibility.',
    'For a global field and finite abelian L/K, reciprocity identifies C_K/N C_L with Gal(L/K); every open finite-index subgroup is such a norm group, with the unique extension in a fixed separable closure. Restriction/corestriction correspond to inclusion/norm.',
    'stated without proof','E','Explicitly attributed classical background. Milne CFT V Theorems5.3 and5.5 give the reciprocity and existence statements, with the finite-quotient convention.', ['MilneCFT2020'])
add(608,[13],'local reciprocity completion',r'$A(K_p)\simeq K_p^*$.',
    'For a nonarchimedean local field, Gal(K_v^ab/K_v)≅widehat(K_v*) under local reciprocity. The uncompleted topological multiplicative group is not profinite.',
    'false as stated','E','The finite norm-quotient assertion is classical and valid. The uncompleted displayed isomorphism fails by the valuation quotient Z. Milne CFT I §1 provides the correct formulation.', ['MilneCFT2020'],'proofs.md C1')
add(609,[15,16],'generalized Jacobian, Picard and Lang symbol',r'$H^1(C,G_m)=J_C(k)$, with $J_C\to\mathbf Z$ and local-symbol diagrams.',
    'For a smooth proper geometrically connected curve over an algebraically closed field, H¹(C,Gm)=Pic(C); the degree-zero piece is the Jacobian, and moduli produce Rosenlicht generalized Jacobians. Over a general field actual line bundles can differ from rational points of the Picard scheme by a Brauer obstruction.',
    'proof sketched','E','Rosenlicht1954 as reported in Koszul1954, and Serre1959, establish generalized Jacobians and local symbols. The degree augmentation prevents replacing the whole Picard group by Pic^0.', ['Koszul1954','Serre1959','Deligne1991'],'Symbol calculations: proofs.md C15; the comparison diagrams themselves are not proofs.')
add(610,[32,33,35],'Ext/cohomology and fundamental two-extension',r'The displayed $\operatorname{Ext}^i$ comparisons and the class $\zeta$ of degree two.',
    'A Picard/generalized-Jacobian object together with a fundamental Ext² class is proposed to encode curve cohomology. An exact theorem requires the site, coefficient category, derived object and degree convention; the displayed comparisons alone do not determine those uniformly.',
    'open on the pages','C','Classical Picard duality and later 1-motive/duality constructions supply special cases, but neither Serre’s pro-quasi-algebraic category nor finite flat duality automatically identifies this whole complex. The exact unrestricted comparison remains unidentifiable without a category dictionary.', ['Serre1960','RibeiroRosengarten2026','Tate1963'],'Yoneda degree addition checked; no asserted general quasi-isomorphism.',confidence='medium')
add(611,[33,34],'splitting with a section and pro-Albanese',r'The zero/splitting claim when a section exists; higher $H^i=\operatorname{Ext}^i$ marked “sans doute”.',
    'A rational base point rigidifies an Albanese/Picard construction and can kill the corresponding extension obstruction; a universal pro-object for rational maps with varying modulus is plausible. Higher Ext formulas need independent comparison theorems.',
    'open on the pages','C','Generalized-Jacobian universal properties and Serre’s inverse limits are established. They do not prove arbitrary higher Ext/cohomology identifications in the unidentified category.', ['Koszul1954','Serre1960','ContouCarrere2013'],confidence='medium')
add(612,[37,38],'Witt series laws',r'$(1+at)*f=f(at)$; $FV=VF=p$; $Vf(t)=f(t^p)$.',
    'In the λ-series model the group law is multiplication of series and Teichmüller multiplication rescales t. In characteristicp, coefficient Frobenius and t↦t^p satisfy FV=VF=[p]. The map to p-typical Witt vectors uses a consistent plus-sign convention.',
    'proof sketched','B','Cartier1967 §1–2 gives the generalized Witt/λ-ring identification and Frobenius–Verschiebung relations, explicitly relating the ring law to Grothendieck’s λ-rings. Exact formulas checked here.', ['Cartier1967'],'proofs.md C2; exact_checks.py Witt_FV_VF_equals_p',date='Cartier note presented12June1967; published1967,265:A49–A52.')
add(613,[40,41,42],'positive cohomology over finite field',r'The proposed vanishing of positive cohomology with constant $\mathbf Z$.',
    'For the discrete constant module Z over F_q, H¹=0 but H²=Q/Z in continuous étale/Galois cohomology. Lang’s theorem for connected algebraic groups does not imply vanishing for Z.',
    'false as stated','E','Corrected by the elementary continuous-cohomology calculation in C3. Classical Galois cohomology supplies the exact sequence; this is not a newly open finite-field question.', ['MilneCFT2020','Serre1960'],'proofs.md C3; exact H² inflation checks')
add(614,[40,41,42],'admissibility and passage to limits',r'“admissibilité” and limit passages explicitly left to check.',
    'The proposed computation of a derived functor by limits of algebraic coefficient groups requires exactness in the specified ind/pro category, including possible lim¹. No category-independent interchange follows.',
    'open on the pages','C','Serre1960 §§2–3 establishes exact inverse limits and enough projectives in his particular pro-quasi-algebraic category. General sheaf and formal categories require different hypotheses; no exact unrestricted statement was identified.', ['Serre1960','SGA3VIIB'],confidence='medium')
add(615,[43],'finite étale H1 and fixed points',r'$H^1(k,G)\simeq G(k)$.',
    'Over F_q, finite étale G corresponds to a finite Frobenius module M and H¹=M/(F−1)M, whereas G(k)=ker(F−1). For constant M the chosen arithmetic Frobenius identifies H¹ with M; there is no asserted natural general identification of invariant and coinvariant functors.',
    'stated without proof','C','Classical procyclic cohomology supplies the corrected coinvariant formula. The literal natural identification needs an extra hypothesis or choice.', ['MilneCFT2020'],'proofs.md C3')
add(616,[45,46,47,48,52,65],'iterated localization and completion',r'The rings along flags and iterated local fields; later “semi-local”.',
    'Along a saturated flag of a noetherian reduced excellent pure-dimensional scheme, successive completion/localization can have finitely many branches. The resulting top factors are finite products of higher local fields; a smooth equicharacteristic two-dimensional flag has the ordered model k((t))((s)).',
    'proof sketched','B','Beilinson adèles and the precise structural theorem in Braunling–Groechenig–Wolfson2016 Thm0.2 develop this construction. Finite branches and the order of operations are essential; the correction on65 is preserved.', ['BGW2016','Yekutieli2003'],'proofs.md C5; exact geometric-series remainder',date='Beilinson1980 announced; structural refinements preprint19Oct2015, published2016.')
add(617,[49,50],'Hom of indecomposable injectives',r'$\operatorname{Hom}(D_p(M),E_q)\simeq M\otimes\operatorname{Hom}(E_p,E_q)$.',
    'For a commutative noetherian ring, indecomposable injectives are E(R/p), and End(E(R/p)) is the completion of R_p. The stated tensor identity is interpreted for M finitely presented over R_p, with the induced R_p-module structure on the Hom coefficient; its exactness implies flatness there.',
    'proof sketched','B','Matlis1958 §§3–4 supplies the injective structure and completion identification. The finite-presentation tensor argument can be checked by a finite presentation and injectivity; it does not justify the subsequent colimit step for sources finite only after localization.', ['Matlis1958'],'Finite-presentation argument and separation from C4 checked.',date='Matlis received10April1958, revised9June1958, publication1958.')
add(618,[51],'Hom through filtered union',r'$\operatorname{Hom}(U_i,K_q)=\varinjlim_j\operatorname{Hom}(U_i,V_j)$.',
    'The interchange fails if U_i is merely finite over R_p. For R=k[[t]], U_i=k((t)), V_j=t^{-j}R/R, every finite-stage Hom is0 but the quotient map to K/R is nonzero. Finite presentation over R repairs the step.',
    'false as stated','C','The correct finite-presentation continuity theorem is established; Matlis theory supplies the concrete injectives. This run refutes the displayed extension of its hypotheses.', ['Matlis1958','EGAIV3'],'proofs.md C4; exact_checks.py Hom_colimit_finite_stage')
add(619,[53,54,55,56],'simplicial coefficients on flags',r'The coefficient functor on chains and the quotient by interior faces, with a degeneracy caveat.',
    'One can construct cosimplicial adèle groups indexed by chains of specializations, with face/degeneracy maps and a normalized complex. Discarding interior faces requires a well-defined quotient and compatibility with the remaining maps; the draft has not supplied all of that compatibility.',
    'open on the pages','C','Yekutieli2003 §1 recalls Beilinson’s exact flasque adelic resolution. This settles the standard cosimplicial construction, not every quotient or restriction proposed here.', ['Yekutieli2003','BGW2016'],confidence='medium')
add(620,[57,58,63,67],'total differential signs',r'$d\prime d\prime\prime=d\prime\prime d\prime$, and $\Theta u+(-1)^{\deg u}u\Theta$.',
    'For commuting square-zero operators a degree sign is needed in totalization. In a graded algebra with Θ²=0, the derivation is d(u)=Θu−(−1)^|u|uΘ. The printed plus version fails d(1)=0 when2Θ≠0.',
    'false as stated','E','Elementary graded algebra repairs the displays. The adèle DG-algebra literature uses compatible signs; mathematical testing cannot decide whether the original ink has the printed signs.', ['Yekutieli2003'],'proofs.md C5; two exact matrix counterexamples')
add(621,[60,61,62,63],'path multiplication associativity',r'Concatenation multiplication; the threefold product checked on63; $\Theta^2=0$.',
    'The finite path algebra of composable chains is associative; imposing the two-sided relation Θ²=0 preserves associativity and permits the graded commutator differential. Infinite-chain sums need a separately specified restricted-product topology.',
    'proved there','B','The finite algebraic part is valid and rechecked. Modern adèles carry a DG product, but no source was identified asserting equality of the manuscript’s entire topological path algebra with a full endomorphism algebra.', ['Yekutieli2003','BGW2016'],'proofs.md C5; exhaustive3,375 path triples')
add(622,[64,65,66,67,68,69],'topologies and residue-complex endomorphisms',r'Multiple topologies, “cosimplicial ?!”, and the comparison with $\operatorname{End}(K^\bullet)$.',
    'The residue complex admits an action of suitable adèles. Identifying all continuous endomorphisms with the proposed restricted path algebra is a stronger statement that depends on topology, chains, normalization and admissibility.',
    'open on the pages','C','Yekutieli2003 Thm0.1 proves the DG-module action for finite-type schemes over a perfect field. BGW2016 Thm0.1 compares three specified Beilinson–Tate operator algebras. Neither is a license to assert the unrestricted draft equality.', ['Yekutieli2003','BGW2016'],confidence='medium')
add(623,[71,72],'Zariski acyclicity of local spectrum',r'Zariski cohomology and locally trivial extensions; the local spectrum is acyclic.',
    'On Spec of a local ring, global sections of arbitrary Zariski abelian sheaves is exact. This says nothing analogous for arbitrary étale or fppf coefficient sheaves.',
    'proof sketched','E','The elementary covering argument proves the statement. SGA2 I–II supplies the local-cohomology framework in which it is used.', ['SGA2'],'proofs.md C6')
add(624,[71,72,73,74],'punctured regular-local cohomology',r'The concentration and completion-invariance calculations for $G_a$ and split linear groups.',
    'For a noetherian regular local R of dimensiond, H_m^i(R)=0 for i≠d. On the punctured spectrum positive O-cohomology shifts by1; for d=1 the boundary is K/R. Passing to the m-adic completion preserves the supported module. Extensions of Ga give the stated split-unipotent dévissage.',
    'proof sketched','A','SGA2 II–III and IV develop these local cohomology and duality calculations. The connected algebraic-group reductions need the algebraically closed/perfect and splitting assumptions stated in the reconstruction.', ['SGA2','Stacks0BJD'],'proofs.md C6–C7')
add(625,[73,74],'abelian/toric reduction in Zariski setting',r'The reduction from a commutative algebraic group to its unipotent part.',
    'For split smooth commutative groups over the indicated algebraically closed field, factoriality of a regular local ring removes the relevant toric Picard terms, and extension of rational maps to abelian varieties removes the specified abelian terms. This is a Zariski claim with degree restrictions.',
    'proof sketched','C','The scalar, factorial and group-structure ingredients are established, but the page is not a proof of the analogous all-degree fppf assertion. The exact topology restriction is retained.', ['SGA2','MilneAGS2012'],'proofs.md C6; no claim of full fppf vanishing.')
add(626,[75,76],'local Jacobian pro-representability',r'$H^d_A(G)=\operatorname{Hom}(J_A,G)$ and the dimension-dependent nature of $J_A$.',
    'The draft proposes a pro-algebraic object representing top supported cohomology on commutative algebraic groups: degree0 includes discrete/abelian pieces, degree1 is linear, higher dimension is unipotent/projective. Exactness alone is insufficient without smallness and pro-representability hypotheses.',
    'stated without proof','C','Serre1960 provides the pro-category formalism; Contou-Carrère2013 proves a precise relative formal-curve universal property. That is a dimension-one result and does not settle the entire higher-dimensional functor on these sheets.', ['Serre1960','ContouCarrere2013','SGA2'],confidence='medium')
add(627,[77,78],'switch to Weil cohomology',r'The linear part is claimed to disappear in positive “Weil” cohomology.',
    'An unrestricted interpretation in fppf cohomology is false: for K=C(x,y), H²(K,Gm) contains the nonzero quaternion(x,y). The unclear qualifier and the different proposed Weil site prevent deciding that this was the intended generality.',
    'open on the pages','F','No category-exact all-degree statement can be identified. The unrestricted reading is refuted, while finite flat/local duality belongs to a different coefficient/site setup.', ['MilneCFT2020','SGA2'],'proofs.md C6, residue y∈C(y)*/C(y)*²',confidence='medium')
add(628,[78],'henselian fundamental group',r'$\pi_1(A)\simeq\pi_1(k)$ for a henselian local ring.',
    'Finite étale algebras over a henselian local ring correspond to finite étale algebras over its residue field, giving the corresponding based fundamental-group isomorphism.',
    'stated without proof','A','SGA1 supplies the finite étale/henselian equivalence. It does not imply equality of all cohomology with arbitrary nonétale coefficients.', ['SGA1'])
add(629,[79],'purity and radicial coefficients',r'The passage from proper/discrete groups to a question about radicial groups.',
    'The extension/purity assertions require separate hypotheses on regularity, codimension and coefficients. Radicial finite flat groups cannot be handled simply by étale topological invariance.',
    'open on the pages','C','Étale invariance is established in SGA1 IX4.10; it intentionally loses infinitesimal groups. Modern finite flat purity is a separate theory, and the unqualified page does not identify one exact theorem.', ['SGA1','SGA3VIIA'],confidence='medium')
add(630,[80,81,82],'Jacobian complex and relative Witt construction',r'$H_0$ is the generalized Jacobian; $H_1=G_m$ in the proper case; unfinished relative/unipotent construction.',
    'The proposal packages the curve’s degree/generalized Picard object and its multiplicative homology into a complex, then seeks a relative Witt/unipotent realization. Degree, properness and modulus matter; the relative construction is not completed.',
    'open on the pages','C','Classical generalized Jacobians and the relative formal-curve universal property are established. An exact comparison for this whole unnamed complex was not located from the searched Serre, Cartier, local-Jacobian and Ext sources.', ['Serre1960','Cartier1967','ContouCarrere2013','RibeiroRosengarten2026'],confidence='medium')
add(631,[84],'fppf fpqc and filtered-limit functors',r'The proposed equivalence of functors and sheaves, with opposite-looking limit symbols.',
    'A finite-presentation representable functor commutes with filtered colimits of rings, and represented group functors satisfy fpqc descent. These are distinct conditions; a displayed direct limit of functors does not equal an inverse limit merely by evaluation.',
    'open on the pages','C','SGA1 VIII and EGAIV3 §8.8 establish descent and limit approximation under explicit hypotheses. The diagram’s whole categorical equivalence is not determined by the transcription.', ['SGA1','EGAIV3','SGA3VIB'],confidence='medium')
add(632,[86],'perfect and quasi-algebraic categories',r'Invert radicial morphisms; the quasi/perfect category diagram.',
    'Over a perfect field, passing to perfect/quasi-algebraic groups inverts purely inseparable isogenies and removes infinitesimal information such as α_p. It changes the coefficient category and its Ext groups.',
    'stated without proof','B','Serre1960 §§1–2 explicitly makes this localization and distinguishes it from Grothendieck’s enlargement to nonreduced group schemes. It is an established construction in the specified category.', ['Serre1960','SGA3VIIA'])
add(633,[89,90],'local duality with supports and shift',r'The local duality diagrams with the $-i-1$ shift.',
    'The proposed local duality is a statement about supported cohomology and a punctured spectrum, so its localization triangle changes the degree by1. Constructibility, finiteness and the precise local site are indispensable.',
    'open on the pages','C','Tate finite-module duality and later sheaf-theoretic local duality settle specified cases; the manuscripts’ general coefficient statement is not a consequence of a degree-free pairing. Cross-linked to the Pro support formulas, where the shifted and unshifted versions differ.', ['Tate1963','SGA2'],confidence='medium')
add(634,[92,93],'tentative Weil site and Rjstar',r'Flat finite-type test objects; “fidèlement plat?” and the $R^i j_*$ question.',
    'The proposed site for a complete DVR with perfect residue field has not fixed its covers and infinitesimal behavior. Comparing generic/special fibers or computing R^i j_* requires those choices.',
    'open on the pages','F','No exact theorem can be assigned before the site is fixed. Modern finite flat/pro-étale duality sources are related comparisons, not identification of the unspecified Rj_*.', ['Serre1960','SGA1','Tate1963'],confidence='low')
add(635,[143],'local finite-module duality',r'Theorem2.1: $H^r(K,M)\times H^{2-r}(K,M^D)\to\mathbf Q/\mathbf Z$.',
    'For a local field and a finite Galois module M of order prime to the characteristic when needed, with Cartier/Tate dual, the cup-product invariant gives finite perfect duality; real places use modified Tate cohomology. Equal-characteristic p-primary finite flat coefficients are treated separately.',
    'stated without proof','B','Tate’s ICM report, §§2–3, contains the finite-module local/global duality programme. The English sheets have matching content; authorship or exact copying cannot be inferred without handwriting/provenance evidence.', ['Tate1963'],date='ICM Stockholm1962; proceedings publication1963,pp288–295.')
add(636,[143],'local Euler characteristic',r'Theorem2.2: $\chi(K,M)=|\#M|_K$.',
    'For a nonarchimedean local field and finite module in Tate’s hypotheses, the alternating product of H⁰,H¹,H² orders equals the normalized local absolute value of #M. Archimedean terms use their separate convention.',
    'stated without proof','B','Established local Euler-characteristic formula in Tate1963 §2. Normalization and coefficient hypotheses are part of the theorem, not optional.', ['Tate1963'],'Finite-order bookkeeping read; no independent proof of the local theorem claimed.')
add(637,[143,144],'unramified annihilators',r'Theorem2.3, equality of unramified H0/H1 orders and H2=0.',
    'For unramified finite coefficients of order invertible in the residue field, the unramified H¹ subgroups in dual modules are mutual annihilators. The residue-field procyclic computation gives the finite H⁰/H¹ cardinality relation; it does not give the false Z vanishing on40.',
    'stated without proof','B','Tate1963 §2 supplies the unramified local pairing result. Its finite prime-to-residue-characteristic condition is retained.', ['Tate1963'],'Procyclic finite-coefficient calculation compared with C3.')
add(638,[144],'equal-characteristic p-primary examples',r'$\mu_p,\alpha_p,\mathbf Z/p$; residue formulas involving $x\,dy/y$ and $x\,dy$.',
    'For K=F_q((t)), flat H¹(μ_p)=K*/K*^p, H¹(α_p)=K/K^p, and H¹(Z/p)=K/(F−1)K. Kummer/Artin–Schreier residue pairings carry their quotient topologies: compact, locally compact and discrete cases differ.',
    'proof sketched','B','The examples belong to finite-flat local duality (the sheet names Shatz1962). The explicit residue blocks are consistent; modern local-duality references in the Pro workstream give the full topological statement.', ['Tate1963','SGA3VIIA'],'proofs.md C10; exact residue matrices',confidence='high')
add(639,[144,145],'Poitou–Tate nine-term sequence',r'Theorem3.1 and its two finite-module corollaries.',
    'For a global field and finite dual coefficients, global/local cohomology is related by the Poitou–Tate sequence with restricted products and Tate modifications at real places. The appropriate Sha¹ and Sha² are dual; finite-S Euler characteristics and reduction to finite Galois groups require the printed ramification restrictions.',
    'stated without proof','B','Tate1963 §3 attributes substantial independent work to Poitou and states the global theorem. This is finite-coefficient duality, not a theorem asserting abelian-variety Sha finiteness.', ['Tate1963'],date='1962 report;1963 publication; Poitou priority distinguished in the report.')
add(640,[146],'abelian-variety global extension and Sha',r'The tentative extension to abelian varieties, involving finiteness of the local–global kernel.',
    'A global abelian-variety duality statement must distinguish its Tate–Shafarevich group from the quotient by its maximal divisible subgroup, and specify completions at degree0. General Sha finiteness cannot be inferred from finite-coefficient duality.',
    'open on the pages','C','Tate1963 Thms3.2–3.4 give the divisible-kernel qualification. Searches through November2026 locate substantial special-case progress, not a verified theorem proving general finiteness for every abelian variety over every global field.', ['Tate1963'],'No independent proof of Sha finiteness is claimed.',confidence='high')
add(641,[148,149,150],'integral and rational l-adic categories',r'Finite étale l-power systems, $M_l\otimes\mathbf Q_l$, and the corrected category diagram.',
    'On a connected scheme with a geometric base point, finite locally constant l-primary systems correspond to continuous π1-modules. Finite-free Z_l systems give continuous integral representations; tensoring with Q_l gives rational ones. Not every ind/pro object is finite-free.',
    'proof sketched','A','SGA1 V establishes the Galois-category equivalence, and Serre1968 I§1 records the lattice formulation. The printed arrow on149 is reversed by its tensor formula and by150.', ['SGA1','Serre1968'],'proofs.md C11')
add(642,[149,150],'existence of stable lattice',r'Every finite-dimensional continuous l-adic representation has an invariant integral lattice.',
    'For a compact profinite group Γ and continuous Γ→GL(V), dim_Ql V finite, there is a Γ-stable finite-free Z_l lattice spanning V.',
    'proof sketched','E','Serre1968 I§1.1 Remark1 gives the finite-orbit lattice proof. The same proof is independently checked here; it is elementary compact-group background rather than a new geometric conjecture.', ['Serre1968'],'proofs.md C11')
add(643,[151,152],'geometric l-adic objects and finite-model descent',r'Tate modules and smooth proper cohomology; inverse-limit descent.',
    'Abelian schemes and smooth proper finite-presentation morphisms provide l-adic systems when l is invertible. Finite-presentation schemes and morphisms descend across filtered inverse limits with affine transitions over qcqs bases; an arbitrary l-adic representation need not descend as one finite object.',
    'stated without proof','A','EGAIV3 §8.8 and SGA3 VIB10.0–10.5 give finite-diagram descent. SGA1 explains finite étale objects; the extra rational representation and smooth proper cohomology comparisons require their separate standard hypotheses.', ['EGAIV3','SGA3VIB','SGA1','Serre1968'])
add(644,[152,153],'finite-type field extensions and image Lie algebra',r'Finite-index image and equality of the associated Lie algebras.',
    'Restriction along a finitely generated extension of fields changes the image of a fixed continuous l-adic Galois representation by finite index; its Lie algebra is unchanged. This uses the finite algebraic-constants extension and finite-dimensional analytic image.',
    'proof sketched','B','Serre1968 I§1.1 Remark2 states precisely invariance under extensions of finite type and refers backward to his work. This is not invariance under arbitrary infinite extensions.', ['Serre1968'],'proofs.md C11')
add(645,[154,155,156],'Serre algebra retained from finite models',r'The model-defined algebra $\mathfrak g$ versus the actual $\mathfrak g\prime$.',
    'A Lie algebra stabilized using finite models can be independent of enlarging those models while strictly exceeding the Lie algebra of the representation on the limiting scheme. The cyclotomic representation after Qbar base change separates the two notions.',
    'proof sketched','C','The finite-type invariance is established in Serre1968. The manuscript’s retained-model definition is not identified with a separately named modern theorem. The unrestricted actual-monodromy reading is false.', ['Serre1968','EGAIV3'],'proofs.md C11, cyclotomic example',confidence='medium')
add(646,[158],'Lie algebra and subgroup germs',r'Closed subgroups, Lie algebras and the assertion that powers landing in H force finite index.',
    'Within compact finite-dimensional l-adic analytic groups, subgroup germs are controlled by Lie subalgebras; if H is closed and every g has a positive power in H, then H is open and finite index. The assertion fails for general compact groups.',
    'open on the pages','B','The analytic Lie formulation is established background (Serre1968 I§1.1 and its Lie reference). The local logarithm proof checks this instance; the product of infinitely many Z/2 refutes its category-free extension.', ['Serre1968'],'proofs.md C11')
add(647,[161,162],'Ext with support as colimit',r'“Th. Supposons F cohérent”; the two comparison maps are isomorphisms.',
    'For X locally noetherian, F coherent, G quasi-coherent, Y cut out by J, the sheaf Ext_Y^i(F,G) is colim_n sheaf Ext^i(F/J^(n+1)F,G). The global version holds for noetherian X. Coherence and the global finiteness condition are retained.',
    'proved there','A','SGA2 II and the injective-torsion argument give this supported Ext calculation; Stacks0BJD and08XW verify its ring-level mechanism. Same claim as the Pro support computation, linked for final consolidation.', ['SGA2','Stacks0BJD','Stacks08XW'],'proofs.md C7')
add(648,[162,163,165],'internal Hom universal rows and rigidity',r'The finite constant rows, Z row, connected-to-unramified zeroes, and proper-to-affine zeroes.',
    'Internal Hom(Z/n,G)=G[n] and Hom(Z,G)=G. Geometrically connected source to étale target gives0; abelian scheme source to affine target gives0. The cell-level supplemental table records every row/column and exceptions.',
    'proof sketched','A','Universal generator arguments and group rigidity establish these entries. SGA3 VIIA gives the group-scheme framework. These are internal Hom functors, not solely field-valued Hom groups.', ['SGA3VIIA','SGA3VIIB'],'proofs.md C8; hom_ext_cells.tsv')
add(649,[162,163,165],'height-one Hom and restricted Lie algebra',r'$\operatorname{Hom}(\alpha_p,G)$ and $\operatorname{Hom}(\mu_p,G)$ as kernels of p-operations.',
    'In characteristicp the restricted-Lie adjunction gives Hom(α_p,G)=ker(x↦x^[p]) and Hom(μ_p,G)=ker(x↦x^[p]−x). This is a group-scheme/functor identity with its nonreduced kernel, not a dimension-only formula.',
    'proof sketched','A','SGA3 VIIA7.2,8.1.1 verifies the adjunction. The handwritten abelian-variety cells require the actual restricted p-map and cannot be filled solely by naming the tangent space.', ['SGA3VIIA'],'proofs.md C8; hom_ext_cells.tsv')
add(650,[162,163,165,189,193],'Cartier V and difficult Hom cells',r'$V=D(G_a)$; $\operatorname{Hom}(V,G)=\underline V(\omega_G)$; questioned $G_a\to V$.',
    'In the formal Cartier-dual category, maps D(G_a)→G correspond to primitive hyperalgebra elements, hence Lie(G). Internal Hom(Ga,Gm) is nonzero on nonreduced rings. The questioned identification Hom(Ga,V)=Ga fails on algebraically closed field points; other formal-valued cells require the dictionary on189.',
    'open on the pages','C','SGA3 VIIB2.2.1–2.2.2 and4.2 provide the formal duality framework. Álvarez–Sancho–Sancho2007 Theorem1 gives a functorial version. The tables mix algebraic and ind/formal language; the supplemental cell audit preserves that boundary.', ['SGA3VIIB','AlvarezSancho2007'],'proofs.md C8; dual-number character and cell-level audit',confidence='medium')
add(651,[164],'geometric Ext elementary table',r'“Ext^1 dans le cas géométrique”; $\operatorname{Ext}^1(Z/n,G)={}^nG$ and starred vanishing cells.',
    'Over an algebraically closed field, geometric Yoneda Ext¹(Z/n,G)=G(k)/nG(k) for the listed finite/smooth coefficients, and Ext¹(Z,G)=0. Finite connected/étale cross-extensions split over a perfect algebraically closed base. These are not formulas for all internal Ext sheaves.',
    'proof sketched','B','Oort1966 ChapterII computes elementary extension groups; finite étale/connected splitting and the constant resolution independently justify the elementary cells. The publisher metadata was opened, while inaccessible detailed theorem numbers are not invented.', ['Oort1966','SGA3VIIA'],'proofs.md C8; hom_ext_cells.tsv',confidence='high')
add(652,[164],'self-extension of alpha_p',r'$\operatorname{Ext}^1(\alpha_p,\alpha_p)=G_a^2\ ?$.',
    'For labelled Yoneda extensions of α_p by α_p over an algebraically closed perfect field, finite Dieudonné modules yield two additive parameters a,b in k, one for F and one for V. This is not the moduli set of middle group schemes up to arbitrary isomorphism.',
    'open on the pages','B','Finite Dieudonné classification supplies the answer; the two-parameter computation is independently reconstructed. Oort1966 and the Oort–Oda1968 formal-module framework identify the category.', ['Oort1966','OortOda1968'],'proofs.md C8; exhaustive finite-field parameter relation checks')
add(653,[164],'Ext from abelian varieties',r'$\operatorname{Ext}(A,G_m)=A\prime$, $\operatorname{Ext}(A,G_a)=H^1(A,O)$; finite coefficients via Tate systems.',
    'Barsotti–Weil identifies geometric Ext¹(A,Gm)=A∨(k), and additive extensions are H¹(A,O). Finite-coefficient formulas need the full finite-group/fppf Tate system in characteristicp, not only the prime-to-p étale Tate module.',
    'stated without proof','B','Ribeiro–Rosengarten TheoremA recovers the degree-one extension identifications and TheoremB proves internal Ext²(A,Gm)=0 over arbitrary bases. Their higher-degree caveat prevents replacing RHom by A∨[−1] without qualification.', ['RibeiroRosengarten2026','Oort1966'],'Category and degree distinction checked; hom_ext_cells.tsv',date='arXiv first20June2025; revised28July2026; publication status as verified by Pro workstream.')
add(654,[164],'higher/geometric extension boundaries',r'The cancelled Ext² remark, question marks and “Consulter travaux Serre”.',
    'The table does not settle all unipotent/abelian mixed cells or any unrestricted higher vanishing. In the category of commutative algebraic groups over algebraically closed k of characteristicp, Ext²(A,B)=0 for abelian varieties A,B; this is a different statement from all internal fppf Ext vanishing.',
    'open on the pages','B','Oort–Oda1968 proves the displayed degree-two algebraic-group theorem. Serre1960 works in the quasi-algebraic category. Ribeiro–Rosengarten2026 records higher fppf nonvanishing, including supersingular characteristic2 in degree3.', ['OortOda1968','Serre1960','RibeiroRosengarten2026'],confidence='high')
add(655,[167,168,169],'primitive torsor and extension',r'The lemma identifying extensions with primitive torsor classes under a normalized rigidity hypothesis.',
    'If normalized maps G^r→γ vanish for r=1,2,3, a pointed primitive γ-torsor on commutative G has a unique compatible commutative extension structure. Geometrically connected G and étale γ give a sufficient case; arbitrary primitive torsors need not satisfy the associativity obstruction automatically.',
    'proved there','E','The page proves associativity/unit and refers the inverse step to Serre1959. The complete normalized-rigidity proof is checked here. Later extension-sheaf results preserve analogous rigidity hypotheses.', ['Serre1959','RibeiroRosengarten2026'],'proofs.md C9, independent completion of inverse and commutativity')
add(656,[169],'étale extensions and universal homeomorphisms',r'The invariance under radicial base change for the étale extension case.',
    'A universal homeomorphism induces an equivalence of étale sites, hence preserves étale torsors and the rigid extension structures just constructed. It does not preserve general finite flat infinitesimal coefficients.',
    'proof sketched','A','SGA1 IX4.10 establishes topological invariance; the original finite-presentation formulation and the integral generalization in the edition’s note are distinguished.', ['SGA1'],'Combines SGA1 invariance with the unique group structure in C9.')
add(657,[170],'Artin–Schreier primitive extensions',r'$\operatorname{Ext}^1(G_a,Z/p)=\Gamma(S,O^{p^{-\infty}})$; Chevalley exposé7 cited.',
    'Over a perfect field, primitive Artin–Schreier classes are represented by a t and identify Ext¹(Ga,Z/p) with the additive field. Over a general characteristicp base the perfection formulation needs its sheaf and base-change conventions.',
    'proof sketched','A','Grothendieck’s Chevalley exposé7,pp8–9, explicitly uses primitive Artin–Schreier polynomials. The perfect-field formula is rechecked; the arbitrary-base display is not extended without its conventions.', ['GrothChevalley7'],'proofs.md C9; additive-polynomial exponent check',date='Seminar1956–1958, exposé7; the supplied page’s chronological relation is undated.')
add(658,[172,173,174,176,177,178,180],'F,V type decomposition',r'Tables of F/V injectivity, surjectivity and nilpotence, with imperfect-base qualifications.',
    'Finite commutative group schemes over a perfect field decompose into étale, multiplicative-local and local-local parts; Cartier duality exchanges F and V. Finite relative Frobenius is an isomorphism precisely in the étale case. Statements about infinite formal/pro objects need their own continuity and boundedness hypotheses.',
    'proof sketched','A','SGA3 VIIA andVIIB establish the finite/infinitesimal structure and duality. The extension of every row to the entire undefined ind/pro category is not established by the finite theorem.', ['SGA3VIIA','SGA3VIIB','Oort1966'],confidence='high')
add(659,[181,182,183,184,197],'gluing formal and algebraic Dieudonné categories',r'The two categories C1,C2 glued along finite local-unipotent groups; $W_\sigma[F,V]$.',
    'The draft seeks an abelian extension category combining algebraic and formal commutative groups and its module description. The coefficient-ring completion, covariance, local nilpotence and topology must be fixed before an equivalence is meaningful.',
    'open on the pages','C','SGA3 VIIB and Oort–Oda1968 provide precise formal-group/hyperalgebra and Dieudonné-module statements. They establish substantial pieces, not an automatic equivalence of the exact unlabelled glued category.', ['SGA3VIIB','OortOda1968','Gabriel1962'],confidence='medium')
add(660,[185,186,188,189,191,192],'field coalgebra/Hopf approximation',r'“Sur un corps” pro(algebraic affine groups)=affine group schemes.',
    'Over a field, every coalgebra is a union of finite-dimensional subcoalgebras, and every commutative Hopf algebra is a filtered union of finitely generated Hopf subalgebras. Dually every affine group scheme is an inverse limit of finite-type affine group schemes.',
    'proof sketched','A','SGA3 VIB11.13 gives the affine approximation; MilneAGS VIII4.6 and8.1–8.2 make the coalgebra and Hopf arguments explicit. The text resolves its own field case by192.', ['SGA3VIB','MilneAGS2012'],'proofs.md C12')
add(661,[186,188,189,191,192],'approximation over a general ring',r'Could finite coalgebras/Hopf algebras suffice over an arbitrary ring, perhaps if A is free?',
    'For a commutative base ring, finite submodules need not remain tensor-injective; one seeks finite/projective or pure subcoalgebras and group approximations satisfying the draft’s additional conditions. The field theorem alone is insufficient.',
    'open on the pages','C','Barr1974 proves general categorical existence results for coalgebras; Kihara2016 proves local finiteness under semihereditary-base/projective-coring hypotheses. These do not settle the manuscript’s unrestricted free-over-arbitrary-ring version. The negative search scope is recorded, not presented as proof that nobody developed it.', ['Barr1974','Kihara2016','SGA3VIIB'],'proofs.md C12; no counterexample to the entire general-ring problem claimed.',confidence='medium')
add(662,[188,189],'Cartier character construction',r'$\Delta f=f\otimes f$, $\varepsilon(f)=1$ and continuous dual algebras.',
    'For an affine group scheme, characters correspond to group-like elements of its Hopf algebra; the antipode makes them units. Over a field, linear duality with the finite-subcoalgebra topology produces the formal/ind Cartier dual. General rings require the flatness/topological hypotheses.',
    'proof sketched','A','SGA3 VIIB2.2.1–2.2.2 gives the precise duality; Álvarez–Sancho–Sancho2007 Theorem1 states a functorial version. The dual is not in general a finite-type scheme.', ['SGA3VIIB','AlvarezSancho2007'],'Hopf counit/antipode calculation; proofs.md C8,C12')
add(663,[189],'elementary Cartier duals',r'$D(G_m)=Z$, $D(Z/p^n)=\mu_{p^n}$, $D(\mu_{p^n})=Z/p^n$.',
    'Cartier duality exchanges Z/n and μ_n. Identifying μ_l with Z/l requires a chosen primitive root and is not canonical. D(Ga) is interpreted as the indicated formal/ind group, not a finite algebraic group.',
    'stated without proof','A','SGA3 VIIA3.3 andVIIB2.2 recover these identities with their categorical variance and noncanonical root choice.', ['SGA3VIIA','SGA3VIIB'],'Group algebra/Hopf duality checked; internal dual-number example retained.')
add(664,[190,191],'pro-object versus ordinary limit',r'“Il importe de bien distinguer” the pro-object and its inverse limit.',
    'The ordinary limit functor generally forgets pro-information. The restricted functor Y↦Hom(Y,X_pro) on original objects need not determine X_pro. The pro-Yoneda embedding uses covariant Hom(X_pro,Y) and opposite variance.',
    'proof sketched','E','The warning is mathematically correct. The finite-set tower makes the distinction explicit; Serre1960 §2 and Gabriel1962 provide the relevant pro/Ind formalism.', ['Serre1960','Gabriel1962'],'proofs.md C12')
add(665,[191],'artinian full-faithfulness question',r'“chaque fois que les objets de C sont artiniens ??”',
    'Artinian objects alone do not make Pro(C)→C′ fully faithful. Finite sets inside Sets satisfy artinianity but maps of ordinary limits can depend discontinuously on infinitely many coordinates.',
    'false as stated','C','Refuted by the explicit binary-sequence example. Adding the topology/continuity or the suitable pro-representability universal property repairs the statement; general pro-category sources do not endorse the printed sufficient condition.', ['Serre1960','Gabriel1962'],'proofs.md C12; finite-prefix witnesses')
add(666,[191,192],'affine schemes as pro finite presentation',r'Pro-(affine schemes of finite type) identified with affine schemes over S.',
    'Over a qcqs base, affine schemes admit inverse-limit descriptions using affine finite-presentation schemes, and finite-presentation Hom commutes with these limits. Finite type suffices over noetherian bases; arbitrary nonnoetherian bases require the stronger hypothesis.',
    'stated without proof','A','EGAIV3 §8.8 and SGA3 VIB10.0 establish finite-presentation approximation. The exact nonnoetherian wording on the page is overbroad if it omits finite presentation.', ['EGAIV3','SGA3VIB'],'proofs.md C12')
add(667,[193],'extension-closed ind-affine group category',r'“catégorie (présumée abélienne)” of ind-affine groups with structures.',
    'The draft proposes an extension category mixing formal, affine and discrete group objects. Abelianity and existence of kernels/cokernels depend on the selected admissible ind-systems and topology; the phrase does not define an exact category.',
    'open on the pages','F','The precise construction is not identifiable. SGA3 formal duality, Serre’s pro-quasi-algebraic groups and Oort’s algebraic groups give distinct established categories, none automatically identical to this unnamed proposal.', ['SGA3VIIB','Serre1960','Oort1966'],confidence='low')
add(668,[195],'Ind length-category correspondence',r'Ind(C) abelian, exact filtered limits, length-finite generators; converse.',
    'For an essentially small abelian length category C, Ind(C) is a Grothendieck abelian category generated by finite-length objects, and its finite-length subcategory is C. Conversely a locally finite-length Grothendieck category is recovered this way.',
    'stated without proof','B','Gabriel1962 ChapterII§4,Theorem1 and the local-finiteness definitions, gives the noetherian/Ind reconstruction; specialization to length categories gives the exact statement. Smallness is supplied explicitly.', ['Gabriel1962'],'Definition and Ind reconstruction checked in downloaded primary full text.')
add(669,[195,196],'socle exhaustion criterion',r'“C loc. de longueur finie ⇔ tout X est le sup des F_i(X)”.',
    'In an arbitrary Grothendieck category, exhaustion by finite socle stages does not imply local finite length. For R=k⊕V,V²=0,dim V infinite, all modules have Loewy length≤2 but R is not a union of finite-length submodules. Local noetherianity repairs the implication.',
    'false as stated','C','Gabriel1962 uses actual finite-length generators, not the weaker criterion. The complete square-zero-ring counterexample and repaired implication are checked here.', ['Gabriel1962'],'proofs.md C13; finite-dimensional shadows explicitly labelled')
add(670,[196],'Krull/Gabriel localization filtration',r'$\Phi_0(X)=\sup F_i(X)$ and kernels of localization at C_i.',
    'A Gabriel filtration by localizing subcategories is defined through localization. Its initial local finite-length torsion radical cannot in general be replaced by finite-socle-stage exhaustion without local noetherian hypotheses; the square-zero example separates them.',
    'stated without proof','C','Gabriel1962 ChapterIV develops the localization/Krull filtration. The unrestricted initial identification on196 is false; the properly defined filtration remains established.', ['Gabriel1962'],'proofs.md C13')
add(671,[197,199,200,201,202],'reasonable formal modules and endomorphism ring',r'Reasonable formal groups, finite-type modules and $M/FM$ of finite length.',
    'A Dieudonné-module classification needs a precise complete ring, covariance, topology and continuity. The finite-socle/artinian step additionally assumes essential socles and artinian injective hulls of simples, as the page itself notes.',
    'open on the pages','C','Gabriel1962 V, SGA3 VIIB and Oort–Oda1968 give precise related categorical/formal-module theorems. They do not determine every undefined “reasonable” object or justify erasing the explicit injective-hull assumption.', ['Gabriel1962','SGA3VIIB','OortOda1968'],confidence='medium')
add(672,[197,200],'Dieudonné ring formulas',r'$FV=VF=p$, semilinear coefficients, and the F/V normal-form products.',
    'With left coefficients, Fw=σ(w)F,Vw=σ^{-1}(w)V and FV=VF=p determine the displayed normal-form multiplications. Writing V=pF^{-1} after inverting F does not invertp.',
    'proof sketched','B','Oort–Oda1968 p82 records the same completed Dieudonné ring. The finite algebraic products and all semilinear coefficient shifts are checked; convergence of infinite series still needs the chosen completion.', ['OortOda1968'],'proofs.md C14; exact Laurent-F model specializations')
add(673,[199],'universal U and nilpotence quantifier',r'$U=\varinjlim\overline W_i$ with the F and p nilpotence line.',
    'The union of all Frobenius-nilpotent finite Witt stages has elementwise bounded F/p nilpotence but no common exponent on the whole union. α_{p^(r+1)} and a Witt vector over k[x]/x^{p^(r+1)} witness the failure for each r.',
    'false as stated','C','Formal Dieudonné theory uses local nilpotence/continuity. The uniform reading is refuted; the possible existential quantifier omitted in transcription remains an ink question.', ['OortOda1968','Cartier1967'],'proofs.md C14')
add(674,[204],'Picard of abelian torsor',r'Action on Pic^0 and NS; $Pic^0(P)=A\prime$ for an A-torsor P.',
    'Translation acts trivially on Pic^0(A) and NS(A). For an A-torsor P, Pic^0(P) is canonically A∨ after descent; the full Picard functor retains its Néron–Severi components and possible rational obstruction.',
    'proof sketched','B','Barsotti–Weil/Picard duality and descent yield the identity; the degree-one extension framework is verified in Ribeiro–Rosengarten. Full Picard points and line bundles remain distinct over nonclosed fields.', ['RibeiroRosengarten2026','Serre1959'])
add(675,[205],'Picard–Brauer Tate pairing',r'$H^1(S,A)\times A\prime(S)\to H^2(S,G_m)$ and derived degree-one pairing.',
    'The Poincaré biextension gives a pairing H¹(S,A)×A∨(S)→H²(S,Gm); equivalently the obstruction to realizing a rational relative line-bundle class on an A-torsor. This does not require falsely concentrating every higher RHom degree.',
    'proof sketched','B','Classical Tate duality and the Barsotti–Weil extension interpretation supply the construction. Ribeiro–Rosengarten’s higher-Ext distinctions ensure the degree-one construction is kept separate from a full derived duality assertion.', ['Tate1963','RibeiroRosengarten2026'],'Yoneda degree shift checked; proofs.md C15')
add(676,[205],'complete cohomology for finite covers',r'The proposed extension to complete/Tate cohomology for a finite cover.',
    'Tate cohomology requires a finite group action (or an explicitly supplied analogous complete resolution), not merely a finite morphism. A finite Galois cover provides the classical setting; general finite flat covers need a different descent formalism.',
    'open on the pages','C','Tate1963 uses finite-group/Tate constructions in the specified contexts. The proposed arbitrary-cover extension is not identified as a theorem.', ['Tate1963','SGA1'],confidence='medium')
add(677,[206],'tame symbol and reciprocity',r'The local formula, skew symmetry, product formula and idèle pairing.',
    'For a smooth proper curve and nonzero rational functions, the valuation/residue tame symbol is bilinear and skew symmetric, and its global normed product is1. At nonrational points residue-field norms are needed; the diagonal sign prevents unqualified alternatingness.',
    'proof sketched','E','Deligne1991 §1 identifies the classical symbol and product formula and attributes the local-symbol framework to Tate/Serre. The sheet uses established background.', ['Deligne1991','Serre1959'],'proofs.md C15; exact P¹ products including infinity')
add(678,[206],'orthogonality and strict units',r'The asserted orthogonality of $K^*$ against $UK^*$.',
    'The inclusion holds with strict local units of residue1, together with reciprocity. It fails if U means all local units: on P¹,f=t and the idele with component2 at0 pair to1/2.',
    'false as stated','C','Classical local symbols give the corrected strict-unit statement. The definition of U must be checked on ink; the literal ordinary-unit interpretation is refuted.', ['Deligne1991','Serre1959'],'proofs.md C15; exact counterexample1/2')
add(679,[207,208],'Albanese-kernel Lang pairing and independence',r'The proposed $N\times C_0\to k^*$ using a Poincaré divisor; independence left unfinished.',
    'A divisor-evaluation construction of a Lang/Tate pairing must carry coherent choices of rational section and trivialization. Replacing Θ by Θ+div(h) changes raw evaluations by h(z); cancellation is an extra compatibility, not an automatic scalar identity.',
    'open on the pages','C','Biextension and local-symbol theories establish properly normalized pairings. No exact proof of the manuscript’s final unrestricted independence sentence was located; its missing choice data are recorded rather than supplied as if present.', ['Deligne1991','Tate1963','RibeiroRosengarten2026'],'proofs.md C15, change-of-divisor factor',confidence='medium')

add(680,[164],'questioned unipotent extension cells',r'The question marks at Ext¹(Ga,Ga), Ext¹(Ga,αp), Ext¹(αp,Ga).',
    'Over algebraically closed k of characteristicp, geometric Yoneda Ext¹(Ga,Ga) is the free left k[F]-module on the length-two Witt extension. Both Ext¹(Ga,αp) and Ext¹(αp,Ga) are one-dimensional over k with their specified scalar actions. These are not arbitrary-base internal Ext sheaf identities.',
    'open on the pages','B','Hazewinkel–Oort report7214 Lemma2.1 proves the Witt formula. The covariant Frobenius sequence proves Ext¹(Ga,alpha_p)=k. The contravariant sequence gives only an injection k into Ext¹(alpha_p,Ga); the separately opened one-dimensionality statement of Fanelli–Schröer2020 p8, citing Oort1966 tableII.14-2, completes that cell. The exact deductions and the degree-two obstruction are recorded in C16.',
    ['HazewinkelOort1972b','FanelliSchroer2020','Oort1966'],'proofs_C16.md; table_checks.py and output',date='Oort table published1966 according to opened2020 primary paper; Hazewinkel–Oort report23June1972 verifies the Witt formula and cites Sharma1967 Theorem7.3, not independently opened here.')
add(681,[164],'finite-kernel reduction for Ga to abelian target',r'$\varinjlim\operatorname{Ext}^1(G_a,{}_nA)$.',
    'Over algebraically closed characteristicp k, Ext¹_alg(Ga,A[p])→Ext¹_alg(Ga,A) is an isomorphism because Hom_alg(Ga,A)=0 and pGa=0. This verifies a finite-kernel reduction; a displayed direct limit additionally needs its transition convention.',
    'stated without proof','B','The exact category of algebraic-group extensions is established in Oort1966; the finite-kernel reduction is independently checked here by its long exact sequence. No claim is made that the opposite αp/A or μp/A cells follow from it.',
    ['Oort1966','HazewinkelOort1972a'],'proofs_C16.md; formal exact-sequence check')

